<section class="container section page-top"><div class="dash-layout"><?php require __DIR__.'/../partials/side_nav.php';?><div class="dash-main"><div class="eyebrow">USER MANAGEMENT</div><h1 class="page-title">Quản lý <em>người dùng</em></h1><div class="panel"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Tên</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td>#<?=$u['id']?></td><td><?=h($u['full_name'])?></td><td><?=h($u['email'])?></td><td><?=h($u['role'])?></td><td><?=$u['status']?'Hoạt động':'Đã khóa'?></td><td><?php if($u['role']!=='admin'):?><form method="post" action="<?=h(url('admin_users'))?>"><?php csrf_field();?><input type="hidden" name="action" value="admin_user_toggle"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-ghost btn-sm"><?=$u['status']?'Khóa':'Mở khóa'?></button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section>
